corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #0A1128;
  font-family: "Playfair Display, serif";
}

>gold = #EAB308;
>silver = #E2E8F0;

rect #jewelCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #0F172A;
  stroke: >gold;
  stroke-width: 1px;
  radius: 4px;
}

text #jewelHeader {
  at: top center of #jewelCard offset 0px 40px;
  content: "SOLITAIRE // ATELIER HAUTE JOAILLERIE";
  font-size: 14px;
  font-weight: 700;
  color: >gold;
}

text #ringTitle {
  at: below #jewelHeader offset 16px;
  content: "L'Étoile 2.4ct • Conflict-Free Brilliance";
  font-size: 30px;
  font-weight: 700;
  color: >silver;
}
